contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take callee and data as arbitrary inputs and an amount of Ether to send
    // to the callee when calling c.forward. The test ensures the contract's
    // balance behavior: on success, the balance can only decrease by at most
    // the forwarded amount; on revert, the balance must remain equal to the
    // pre-call balance.
    function run(address callee, bytes calldata data, uint256 amount) public payable {
        // ensure this contract has enough balance to send 'amount' when needed
        require(address(this).balance >= amount);

        // record c's balance before the call
        uint256 before = address(c).balance;

        bool reverted;
        // perform the forwarded call inside try/catch to detect revert
        try c.forward{value: amount}(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule:
        // - If the call reverted, c's balance must be unchanged.
        // - If the call succeeded, c's balance cannot have increased, and may have
        //   decreased by at most 'amount' (the forwarded value).
        assert(
            reverted
            ? (after == before)
            : (after <= before && before - after <= amount)
        );
    }

    receive() external payable {}
}

